import sys

def main():
    s = sys.stdin.readline().rstrip('\n')
    words = s.split()
    if not words:
        print(-1)
        return
    max_word = words[0]
    for word in words[1:]:
        if len(word) > len(max_word):
            max_word = word
    print(max_word)

if __name__ == "__main__":
    main()
